package io.mateu.ijp.figma

import com.fasterxml.jackson.databind.JsonNode
import com.fasterxml.jackson.databind.ObjectMapper
import java.io.File
import junit.framework.TestCase

/**
 * The Figma import corpus (conformance/client/figma-import.json, generated by the VS Code
 * extension's figmaImport.ts) — the same file the Maven goal runs: Figma URL → key, the routes
 * file chosen, the minimal routes.yaml append.
 */
class FigmaImportConformanceTest : TestCase() {

    private fun corpus(): JsonNode {
        var dir: File? = File("").absoluteFile
        while (dir != null) {
            val f = File(dir, "conformance/client/figma-import.json")
            if (f.isFile) return ObjectMapper().readTree(f)
            dir = dir.parentFile
        }
        error("conformance/client/figma-import.json not found above ${File("").absolutePath}")
    }

    fun testFileKeys() {
        val failures = ArrayList<String>()
        for (c in corpus().path("fileKeys")) {
            val input = c.path("input").asText()
            val got = runCatching { FigmaImport.fileKey(input) }
            if (c.path("error").asBoolean()) {
                if (got.isSuccess) failures += "\"$input\": expected an error, got ${got.getOrNull()}"
            } else if (got.getOrNull() != c.path("key").asText()) {
                failures += "\"$input\": expected ${c.path("key").asText()}, got $got"
            }
        }
        assertTrue(failures.joinToString("\n"), failures.isEmpty())
    }

    fun testRouteAppends() {
        for (c in corpus().path("routeAppends")) {
            val got = FigmaImport.appendImportedRoute(c.path("text").asText(), c.path("route").asText(), c.path("layout").asText())
            val expected = c.path("expected").takeUnless { it.isNull }?.asText()
            assertEquals(c.path("name").asText(), expected, got)
        }
    }

    fun testPageRoutesAndRoutesFiles() {
        for (c in corpus().path("pageRoutes")) assertEquals(c.path("route").asText(), FigmaImport.routeOfPage(c.path("path").asText()))
        for (c in corpus().path("routesFiles")) {
            val chosen = FigmaImport.routesFileFor(c.path("files").map { it.asText() })
            assertEquals(c.path("chosen").takeUnless { it.isNull }?.asText(), chosen)
        }
    }
}
